def clean(df):
    df = df.drop_duplicates().reset_index(drop=True)
    df['Quantity'] = df['Quantity'].abs()
    df['Category'] = df['Category'].str.strip()
    df['Price'] = df['Price'].str.replace('$', '', regex=False).str.replace('.00', '', regex=False)
    return df

def answer(df):
    return df.groupby('Region')['Quantity'].sum().to_dict()
